'use strict';
const $=s=>document.querySelector(s);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'<path d="M3 10 12 3l9 7v10h-6v-7H9v7H3z"/>',light:'<path d="M9 18h6m-5 3h4M8 15a7 7 0 1 1 8 0l-1 2H9z"/>',tv:'<rect x="2" y="4" width="20" height="14" rx="2"/><path d="M8 22h8m-4-4v4"/>',ai:'<circle cx="12" cy="12" r="9"/><path d="M5 12h3l2-4 3 8 2-4h4"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2"/><circle cx="12" cy="12" r="8"/>',power:'<path d="M12 2v10M6 5a9 9 0 1 0 12 0"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2"/>',moon:'<path d="M20 15A9 9 0 0 1 9 4a9 9 0 1 0 11 11z"/>',book:'<path d="M12 5v15M3 4q5-1 9 3 4-4 9-3v15q-5-1-9 2-4-3-9-2z"/>',film:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="M7 4v16m10-16v16M3 9h4m10 0h4M3 15h4m10 0h4"/>',bath:'<path d="M3 12h18v3a5 5 0 0 1-5 5H8a5 5 0 0 1-5-5zM6 12V5a2 2 0 0 1 4 0v1"/>',closet:'<path d="M5 3h14v18H5zM12 3v18m-2-10v2m4-2v2"/>',volume:'<path d="M3 9v6h4l5 4V5L7 9zM16 8q5 4 0 8m3-11q8 7 0 14"/>',mic:'<rect x="9" y="2" width="6" height="13" rx="3"/><path d="M5 10v2a7 7 0 0 0 14 0v-2m-7 9v3m-4 0h8"/>',spark:'<path d="M12 2 14 9l7 3-7 2-2 8-2-8-7-2 7-3z"/>'};
function icon(n,off=false){return `<span class="icon ${off?'off':''}" aria-hidden="true"><svg viewBox="0 0 24 24">${paths[n]||paths.light}</svg></span>`}
const defaults={scene:'Evening',lights:[{id:'bedside',name:'Bedside lamp',room:'Bedroom',b:45,k:2700,on:true},{id:'floor',name:'Statement floor lamp',room:'Bedroom',b:35,k:2700,on:true},{id:'desk',name:'Desk lamp',room:'Bedroom',b:20,k:3000,on:true},{id:'tvlight',name:'TV backlighting',room:'Bedroom',b:15,k:2700,on:true},{id:'bath',name:'Vanity lights',room:'Bathroom',b:70,k:3000,on:false},{id:'closet',name:'Closet lights',room:'Closet',b:70,k:3000,on:false}],tv:false,volume:30,musicLinks:[]};
let state;try{state={...JSON.parse(JSON.stringify(defaults)),...JSON.parse(localStorage.getItem('home-v1')||'{}')}}catch{state=JSON.parse(JSON.stringify(defaults))};let tab='Overview',room='All',busy=false,timer=null,backend=false;
const scenes={Morning:{i:'sun',b:[80,70,60,0,100,75],k:3500,tv:false},Focus:{i:'book',b:[20,45,100,0,0,0],k:4000,tv:false},Cinema:{i:'film',b:[0,10,0,25,0,0],k:2700,tv:true},Evening:{i:'moon',b:[45,35,20,15,0,0],k:2700,tv:false},Relax:{i:'spark',b:[25,20,0,10,0,0],k:2400,tv:false},Sleep:{i:'moon',b:[0,0,0,0,0,0],k:2700,tv:false}};
const navs={Overview:'home',Lighting:'light',Media:'tv',Settings:'settings'};
function save(){delete state.chat;delete state.memory;delete state.speak;try{localStorage.setItem('home-v1',JSON.stringify(state))}catch{}}function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(timer);timer=setTimeout(()=>$('#toast').style.display='none',2200)}
function choose(s){let v=scenes[s];state.scene=s;state.lights=state.lights.map((l,i)=>({...l,b:v.b[i]||l.b,on:v.b[i]>0,k:v.k}));state.tv=v.tv;save();render();toast(s+' scene activated · simulated')}
function navigate(t){tab=t;if(t==='Calendar')selectedDay=dayKey();if(t==='Overview')nightDismissed=periodNow();render();window.scrollTo(0,0)}function clock(){let d=new Date();let hero=$('#heroClock');if(hero)hero.textContent=d.toLocaleTimeString([], {hour:'numeric',minute:'2-digit'}).replace(/\s*(AM|PM)$/i,'');$('#clock').textContent=d.toLocaleTimeString([], {hour:'numeric',minute:'2-digit'});$('#date').textContent=d.toLocaleDateString([], {weekday:'long',month:'long',day:'numeric'})}clock();setInterval(clock,1000);
function sceneCards(){return `<div class="scenes">${Object.entries(scenes).map(([n,s])=>`<button class="scene ${n===state.scene?'active':''}" data-scene="${n}" aria-pressed="${n===state.scene}">${icon(s.i)}${n}</button>`).join('')}</div>`}
function tile(i,label,value,detail,go){return `<button class="tile" style="text-align:left;color:inherit" data-tab="${go}"><div class="tiletop">${icon(i)}<span class="muted">↗</span></div><div class="big">${value}</div><h3>${label}</h3><div class="muted">${detail}</div></button>`}
function lighting(){let list=state.lights.filter(l=>room==='All'||l.room===room);return `<div class="between"><h2>Lighting studio</h2><button class="secondary" data-action="all">${state.lights.some(l=>l.on)?'All off':'All on'}</button></div><div class="tabs">${['All','Bedroom','Bathroom','Closet'].map(r=>`<button class="pill ${r===room?'active':''}" data-room="${r}">${r}</button>`).join('')}</div><div class="grid two">${list.map(l=>`<div class="tile ${l.on?'active':''}"><div class="tiletop">${icon('light',!l.on)}<button class="power ${l.on?'on':''}" aria-label="Toggle ${esc(l.name)}" aria-pressed="${l.on}" data-toggle="${l.id}">${icon('power')}</button></div><h3>${esc(l.name)}</h3><div class="muted">${l.room}</div><div class="big" id="b-${l.id}">${l.on?l.b:0}%</div><input type="range" min="0" max="100" value="${l.on?l.b:0}" aria-label="${esc(l.name)} brightness" data-bright="${l.id}"><div class="between muted"><span>Warmth</span><span id="k-${l.id}">${l.k}K</span></div><input type="range" min="2200" max="6500" step="100" value="${l.k}" aria-label="${esc(l.name)} color temperature" data-temp="${l.id}"></div>`).join('')}</div><section class="section"><h2>Scenes</h2>${sceneCards()}</section>`}
paths.music='<path d="M9 18V5l12-2v13M9 9l12-2"/><ellipse cx="6" cy="18" rx="3" ry="2.5"/><ellipse cx="18" cy="16" rx="3" ry="2.5"/>';
function musicCard(){return `<div class="musiccard"><div class="musicart">${icon('music')}</div><div><h3>Apple Music</h3><p class="muted">Your library, playlists and listening.</p><a class="musiclink" href="https://music.apple.com/" target="_blank" rel="noopener noreferrer">Open Apple Music ↗</a></div></div><p class="note">Opens Apple Music separately. Playback and library access are not connected to HOME.</p>`}
function media(){return `${streamingLinks()}<div class="panel section"><div class="tvscreen ${state.tv?'':'off'}"><div>${icon('tv',!state.tv)}<div><strong>${state.tv?'HOME TV':'Standby'}</strong></div><div class="muted">Virtual 55-inch display</div></div></div><div class="between"><div><h2 style="margin:0">Entertainment</h2><div class="muted">Hisense · future Google TV integration</div></div><button class="power ${state.tv?'on':''}" data-action="tv" aria-label="Toggle TV" aria-pressed="${state.tv}">${icon('power')}</button></div><section class="section"><div class="between"><h3>Surround sound</h3><span id="vol">${state.volume}%</span></div><input type="range" min="0" max="100" value="${state.volume}" data-volume aria-label="Virtual audio volume"></section><button class="primary" data-scene="Cinema">Activate cinema mode</button></div><p class="note">This is a simulated remote. Streaming apps, volume and television power will require compatible hardware integrations.</p>`}
function settings(){return `<div class="panel"><h2>System</h2><div class="setting between"><div><h3>Device adapter</h3><div class="muted">Simulation · real integration not configured</div></div><span class="tag">Local</span></div><div class="setting between"><div><h3>Reset HOME</h3><div class="muted">Remove local data and return to defaults</div></div><button class="secondary" data-action="reset">Reset</button></div></div>`}
function render(){document.body.dataset.page=tab.toLowerCase();$('#heading').textContent=({Overview:'HOME',Calendar:'Calendar',Tasks:'Tasks',Focus:'Focus',Goals:'Goals',Lighting:'Lighting',Media:'Entertainment',Weather:'Weather',Settings:'Settings'})[tab];$('#nav').innerHTML=navOrder.map(n=>[n,navs[n]]).map(([n,i])=>`<button class="navbtn ${n===tab?'active':''}" data-tab="${n}" aria-label="${n}" ${n===tab?'aria-current="page"':''}>${icon(i)}<span>${n==='Overview'?'Home':n==='Media'?'Music & TV':n}</span></button>`).join('');$('#view').innerHTML=({Overview:todayView,Calendar:calendarView,Tasks:tasksView,Focus:focusView,Goals:goalsView,Lighting:lighting,Media:media,Weather:()=>weatherPanel(true),Settings:settingsV3})[tab]()}
Object.assign(paths,{calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v4m10-4v4M3 10h18m-13 4h2m4 0h2m-8 4h2"/>',tasks:'<circle cx="12" cy="12" r="9"/><path d="m8 12 3 3 5-6"/>',timer:'<circle cx="12" cy="13" r="8"/><path d="M9 2h6m-3 3V2m0 11V8m6-2 2-2"/>',plus:'<path d="M12 5v14M5 12h14"/>',left:'<path d="m15 5-7 7 7 7"/>',right:'<path d="m9 5 7 7-7 7"/>',bed:'<path d="M3 18V7m18 11V7M3 16h18M3 11h18v5M6 11V7h5v4m2 0V7h5v4"/>',edit:'<path d="m4 16 12-12 4 4-12 12H4zM13 7l4 4"/>',trash:'<path d="M4 6h16M9 6V3h6v3m3 0-1 15H7L6 6m4 4v7m4-7v7"/>',journal:'<rect x="5" y="3" width="15" height="18" rx="2"/><path d="M9 3v18m3-12h5m-5 4h5"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>'});
Object.assign(navs,{Calendar:'calendar',Tasks:'tasks',Focus:'timer'});
const navOrder=['Overview','Calendar','Tasks','Focus','Goals','Lighting','Media','Weather','Settings']; Object.assign(navs,{Goals:'target',Weather:'cloud'});
const freshPlan=()=>({events:[],tasks:[],logs:[],focus:{minutes:25,remaining:1500,end:0,label:'Study'},goals:[]});
let plan;try{plan={...freshPlan(),...JSON.parse(localStorage.getItem('home-plan-v3')||'{}')}}catch{plan=freshPlan()}
function savePlan(){delete plan.journal;try{localStorage.setItem('home-plan-v3',JSON.stringify(plan));if(typeof syncCapture==='function')syncCapture()}catch{toast('Storage unavailable. Export a backup.')}}
const dayKey=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const asDate=k=>new Date(k+'T12:00:00');const shift=(k,n)=>{let d=asDate(k);d.setDate(d.getDate()+n);return dayKey(d)};const pretty=k=>asDate(k).toLocaleDateString([], {weekday:'short',month:'short',day:'numeric'});const uid=()=>globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2);
let selectedDay=dayKey(),calMode='Month',taskFilter='Open';
function eventsOn(k){return plan.events.filter(e=>e.date===k).sort((a,b)=>a.time.localeCompare(b.time))}function fmtTime(t){if(!t)return 'All day';let [h,m]=t.split(':').map(Number);return `${h%12||12}:${String(m).padStart(2,'0')} ${h>=12?'PM':'AM'}`}
function head(i,t,button=''){return `<div class="cardhead">${icon(i)}<h2>${t}</h2>${button}</div>`}function link(t,label){return `<button class="textbutton" data-tab="${t}">${label} ›</button>`}function addBtn(kind,label='Add'){return `<button class="secondary" data-new="${kind}">${icon('plus')} ${label}</button>`}
function eventRows(es,editable=false){return es.length?es.map(e=>`<div class="event"><div class="eventbar" style="background:${eventColors[e.color]||eventColors.Blue}"></div><div class="eventbody"><small>${esc(fmtTime(e.time))}${e.end?' – '+esc(fmtTime(e.end)):''}</small><strong>${esc(e.title)}</strong>${e.notes?`<small>${esc(e.notes)}</small>`:''}</div>${editable?`<button class="tiny" data-edit="event:${esc(e.id)}" aria-label="Edit event">${icon('edit')}</button>`:''}</div>`).join(''):'<p class="empty">Nothing scheduled. Your day is yours to plan.</p>'}
function taskRows(ts,editable=false){return ts.length?ts.map(t=>`<div class="taskrow ${t.done?'done':''}"><input type="checkbox" data-task="${esc(t.id)}" ${t.done?'checked':''} aria-label="Complete ${esc(t.title)}"><span>${esc(t.title)}${t.due?`<small class="muted" style="display:block">${esc(pretty(t.due))}</small>`:''}</span>${editable?`<button class="tiny" data-edit="task:${esc(t.id)}" aria-label="Edit task">${icon('edit')}</button>`:''}</div>`).join(''):'<p class="empty">Nothing here yet.</p>'}
function focusRemaining(){return plan.focus.end?Math.max(0,Math.ceil((plan.focus.end-Date.now())/1000)):plan.focus.remaining}function countdown(){let v=focusRemaining();return `${String(Math.floor(v/60)).padStart(2,'0')}:${String(v%60).padStart(2,'0')}`}
function focusCard(){let progress=Math.max(0,Math.min(100,focusRemaining()/(plan.focus.minutes*60)*100));return `<div class="focus-ring" id="focusRing" style="--progress:${progress}%"><div class="focus-inner"><div class="focusface" id="focusClock">${countdown()}</div><p class="muted">${esc(plan.focus.label)}</p></div></div><div class="focusactions"><button class="circle-action" data-focus="reset" aria-label="Reset timer">${icon('reset')}</button><button class="play-action" data-focus="${plan.focus.end?'pause':'start'}" aria-label="${plan.focus.end?'Pause':'Start'} timer">${icon(plan.focus.end?'pause':'play')}</button><button class="circle-action" data-tab="Focus" aria-label="Focus settings">${icon('settings')}</button></div>`}
function roomCards(){return `<div class="roomcards">${[{n:'Bedroom',i:'bed',r:'Bedroom'},{n:'Bathroom',i:'bath',r:'Bathroom'},{n:'Closet',i:'closet',r:'Closet'},{n:'Entertainment',i:'tv',}].map(x=>`<button class="roomcard" ${x.r?`data-roomgo="${x.r}"`:'data-tab="Media"'}>${icon(x.i)}<div><strong>${x.n}</strong><small>${x.r?state.lights.filter(l=>l.room===x.r&&l.on).length+' lights on':state.tv?'Playing · simulated':'Standby'}</small></div></button>`).join('')}</div>`}
function originalTodayView(){let now=new Date(),hour=now.getHours(),done=plan.tasks.filter(t=>t.done).length,all=plan.tasks.length;return `<p class="greeting">Good ${hour<12?'morning':hour<18?'afternoon':'evening'}. Make space for what matters.</p><div class="dashgrid"><section class="glass">${head('calendar','Schedule',link('Calendar','Calendar'))}${eventRows(eventsOn(dayKey()).slice(0,4))}<button class="textbutton" data-new="event">${icon('plus')} New event</button></section><section class="glass">${head('tasks','Reminders',link('Tasks','All tasks'))}<div class="muted">${done} of ${all} completed</div><div class="progress"><span style="width:${all?done/all*100:0}%"></span></div>${taskRows(plan.tasks.filter(t=>!t.done).slice(0,3))}<button class="textbutton" data-new="task">${icon('plus')} New task</button></section><section class="glass">${head('timer','Focus',link('Focus','Session'))}${focusCard()}</section><section class="glass">${head('music','Music',link('Media','Media'))}${musicCard()}</section></div><section class="section"><div class="between sectionhead"><h2>Your space</h2><span class="tag">Simulation</span></div>${roomCards()}</section><section class="section"><div class="between sectionhead"><h2>Scenes</h2>${link('Lighting','Lighting')}</div>${sceneCards()}</section>`}
function calendarView(){let d=asDate(selectedDay),start=dayKey(new Date(d.getFullYear(),d.getMonth(),1)),offset=asDate(start).getDay(),weekStart=shift(selectedDay,-d.getDay()),base=calMode==='Month'?shift(start,-offset):weekStart,n=calMode==='Month'?42:7;let cells=Array.from({length:n},(_,i)=>{let k=shift(base,i),dt=asDate(k),es=eventsOn(k);return `<button class="daycell ${k===selectedDay?'selected':''} ${k===dayKey()?'today':''} ${calMode==='Month'&&dt.getMonth()!==d.getMonth()?'other':''}" data-day="${k}" aria-label="${pretty(k)}"><span class="daynum">${dt.getDate()}</span>${es.slice(0,calMode==='Month'?2:5).map(e=>`<span class="eventchip" style="border-left:3px solid ${eventColors[e.color]||eventColors.Blue}">${esc(e.title)}</span>`).join('')}${es.length>(calMode==='Month'?2:5)?'<span class="subtle">More</span>':''}</button>`}).join('');return `<div class="calendarbar"><div class="row"><button class="tiny" data-calnav="-1" aria-label="Previous">${icon('left')}</button><h2>${calMode==='Month'?d.toLocaleDateString([],{month:'long',year:'numeric'}):pretty(selectedDay)}</h2><button class="tiny" data-calnav="1" aria-label="Next">${icon('right')}</button><button class="textbutton" data-calnav="today">Today</button></div><div class="tabs">${['Day','Week','Month'].map(m=>`<button class="pill ${calMode===m?'active':''}" data-calmode="${m}">${m}</button>`).join('')}</div>${addBtn('event','Event')}</div>${calMode!=='Day'?`<div class="glass"><div class="monthgrid">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(x=>`<div class="weekday">${x}</div>`).join('')}</div><div class="${calMode==='Month'?'monthgrid':'weekgrid'}">${cells}</div></div>`:''}<section class="section glass">${head('calendar',pretty(selectedDay),`<button class="textbutton" data-new="event">+ Add</button>`)}${eventRows(eventsOn(selectedDay),true)}</section><p class="note">HOME calendar is stored on this device. Export events to an .ics file in Settings to import into Apple Calendar; native two-way integration is not connected yet.</p>`}
function tasksView(){let done=plan.tasks.filter(t=>t.done).length,all=plan.tasks.length;let list=plan.tasks.filter(t=>taskFilter==='All'||(taskFilter==='Done'?t.done:!t.done));return `<div class="between"><div><h2>Your priorities</h2><p class="muted">${done} of ${all} completed</p></div>${addBtn('task','Task')}</div><div class="tabs">${['Open','Done','All'].map(f=>`<button class="pill ${taskFilter===f?'active':''}" data-taskfilter="${f}">${f}</button>`).join('')}</div><div class="glass"><div class="progress"><span style="width:${all?done/all*100:0}%"></span></div>${taskRows(list,true)}</div><section class="section glass">${head('target','Goals',`<button class="textbutton" data-new="goal">+ Add goal</button>`)}${plan.goals.length?plan.goals.map(g=>`<div class="taskrow ${g.done?'done':''}"><input type="checkbox" data-goal="${esc(g.id)}" ${g.done?'checked':''} aria-label="Complete goal"><span>${esc(g.title)}</span><button class="tiny" data-edit="goal:${esc(g.id)}" aria-label="Edit goal">${icon('edit')}</button></div>`).join(''):'<p class="empty">Set an intention for your week or month.</p>'}</section>`}
function focusView(){let today=plan.logs.filter(x=>dayKey(new Date(x.at))===dayKey()),minutes=today.reduce((s,x)=>s+x.minutes,0);return `<div class="dashgrid"><section class="glass">${head('timer','Deep work')}${focusCard()}<div class="tabs" style="justify-content:center">${[25,50,90].map(m=>`<button class="pill ${plan.focus.minutes===m?'active':''}" data-duration="${m}" ${plan.focus.end?'disabled':''}>${m} min</button>`).join('')}</div><label class="muted">Activity<select id="focusLabel" ${plan.focus.end?'disabled':''}>${['Study','Work','Reading','Chores','Exercise','Personal'].map(x=>`<option ${x===plan.focus.label?'selected':''}>${x}</option>`).join('')}</select></label></section><section class="glass">${head('target','Today')}<div class="big">${minutes} min</div><p class="muted">Completed focus time · ${today.length} sessions</p><div class="section">${addBtn('log','Log time manually')}</div></section></div><section class="section glass">${head('journal','Activity history')}${plan.logs.length?[...plan.logs].reverse().map(x=>`<div class="logrow"><div><strong>${esc(x.label)}</strong><div class="muted">${esc(pretty(dayKey(new Date(x.at))))}</div></div><div>${x.minutes} min <button class="tiny" data-edit="log:${esc(x.id)}" aria-label="Edit log">${icon('edit')}</button></div></div>`).join(''):'<p class="empty">Completed sessions will appear here.</p>'}</section>`}
function originalSettingsV3(){return `<section class="glass"><h2>Data & connectivity</h2><div class="setting"><h3>Offline-first storage</h3><p class="muted">Your calendar, tasks and preferences stay on this browser. Install from an HTTPS address (or localhost) and open once online for offline loading. An ordinary HTTP LAN address cannot cache the app on iPad.</p><div class="syncbuttons"><button class="secondary" data-data="export">Export backup</button><button class="secondary" data-data="import">Import backup</button><button class="secondary" data-data="ics">Export calendar (.ics)</button></div></div><div class="setting"><h3>iPhone & iPad</h3><p class="muted">Install the same free static app on both devices. Transfer the JSON backup using AirDrop or Files. Import replaces local data; back up both devices first. Automatic cross-device sync and live Apple Calendar access are not implemented.</p></div></section><section class="section">${settings()}</section>`}
const collections={event:'events',task:'tasks',goal:'goals',log:'logs'};
function openEditor(kind,id){let arr=plan[collections[kind]],item=arr.find(x=>x.id===id)||{},title=kind==='log'?'Activity':kind[0].toUpperCase()+kind.slice(1);let fields=`<label>${kind==='log'?'Activity':'Title'}<input name="title" required maxlength="150" value="${esc(item.title||item.label||'')}"></label>`;if(kind==='event')fields+=`<label>Date<input type="date" name="date" required value="${esc(item.date||selectedDay)}"></label><label>Start time (optional)<input type="time" name="time" value="${esc(item.time||'')}"></label><label>End time (optional)<input type="time" name="end" value="${esc(item.end||'')}"></label><label>Notes<textarea name="notes" maxlength="1000">${esc(item.notes||'')}</textarea></label>`;if(kind==='event')fields+=`<label>Calendar color<select name="color">${['Blue','Purple','Green','Orange','Pink'].map(c=>`<option ${item.color===c?'selected':''}>${c}</option>`).join('')}</select></label>`;if(kind==='goal')fields+=`<label>Progress<input type="number" name="progress" min="0" max="100000000" step="any" required value="${Number(item.progress??(item.done?1:0))}"></label><label>Target<input type="number" name="target" min="0.01" max="100000000" step="any" required value="${Number(item.target||1)}"></label><label>Unit (optional)<input name="unit" maxlength="20" value="${esc(item.unit||'')}" placeholder="sessions, dollars, hours…"></label>`;if(kind==='task')fields+=`<label>Due date (optional)<input type="date" name="due" value="${esc(item.due||'')}"></label>`;if(kind==='journal')fields+=`<label>Date<input type="date" name="date" required value="${esc(item.date||dayKey())}"></label><label>Reflection<textarea name="text" required maxlength="10000">${esc(item.text||'')}</textarea></label>`;if(kind==='log')fields+=`<label>Minutes<input type="number" name="minutes" min="1" max="1440" required value="${item.minutes||25}"></label>`;let el=$('#editor');el.innerHTML=`<h2>${id?'Edit':'New'} ${title.toLowerCase()}</h2><form id="itemForm" class="formgrid" data-kind="${kind}" data-id="${esc(id||'')}">${fields}<div class="between">${id?`<button type="button" class="secondary" data-delete="${kind}:${esc(id)}">Delete</button>`:'<span></span>'}<div class="row"><button type="button" class="secondary" data-close>Cancel</button><button class="primary" type="submit">Save</button></div></div></form>`;el.showModal()}
function commitEditor(form){let f=Object.fromEntries(new FormData(form)),kind=form.dataset.kind,id=form.dataset.id||uid(),arr=plan[collections[kind]],old=arr.find(x=>x.id===id)||{};let item={id,title:f.title.trim()};if(!item.title)return;if(kind==='event'){if(f.end&&(!f.time||f.end<=f.time)){toast('End time must be after start time.');return}Object.assign(item,{date:f.date,time:f.time,end:f.end,notes:f.notes,color:f.color})}if(kind==='task')Object.assign(item,{due:f.due,done:!!old.done});if(kind==='goal'){item.target=Number(f.target);item.progress=Math.min(Number(f.progress),item.target);item.unit=f.unit.trim();item.done=item.progress>=item.target;}if(kind==='log')item={id,label:item.title,minutes:Number(f.minutes),at:old.at||Date.now()};let i=arr.findIndex(x=>x.id===id);if(i<0)arr.push(item);else arr[i]=item;if(kind==='event')selectedDay=item.date;savePlan();$('#editor').close();render();toast('Saved on this device')}
function downloadFile(name,text,type){let a=document.createElement('a'),u=URL.createObjectURL(new Blob([text],{type}));a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),30000)}
function exportBackup(){delete plan.journal;delete state.chat;delete state.memory;delete state.speak;downloadFile('HOME-backup-'+dayKey()+'.json',JSON.stringify({version:3,plan,state},null,2),'application/json')}
function importBackup(raw){let j=JSON.parse(raw);if(j.version!==3||!j.plan||!j.state)throw Error('Not a HOME v0.3 backup');for(let k of ['events','tasks','goals','logs'])if(!Array.isArray(j.plan[k])||j.plan[k].length>10000)throw Error('Invalid backup');for(let [k,arr] of Object.entries(j.plan)){if(k==='focus')continue;if(!Array.isArray(arr))continue;for(let x of arr)if(!x||typeof x.id!=='string'||(k==='logs'?typeof x.label!=='string':typeof x.title!=='string'))throw Error('Invalid items')}for(let x of j.plan.events)if(typeof x.date!=='string'||typeof x.time!=='string')throw Error('Invalid calendar');if(!Array.isArray(j.state.lights)||j.state.lights.length!==6)throw Error('Invalid settings');if(!confirm('Replace this device’s HOME data with the backup?'))return;plan={...freshPlan(),...j.plan};plan.focus={...freshPlan().focus,...j.plan.focus,end:0};state={...defaults,...j.state};savePlan();save();render();toast('Backup imported')}
function exportICS(){const clean=s=>String(s||'').replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/[,;]/g,m=>'\\'+m);let now=new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d+Z/,'Z');let lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//HOME//Calendar//EN','CALSCALE:GREGORIAN'];for(let e of plan.events){let d=e.date.replace(/-/g,''),dt=t=>d+'T'+t.replace(':','')+'00';lines.push('BEGIN:VEVENT','UID:'+clean(e.id)+'@home.local','DTSTAMP:'+now,'SUMMARY:'+clean(e.title),e.time?'DTSTART:'+dt(e.time):'DTSTART;VALUE=DATE:'+d);if(e.end)lines.push('DTEND:'+dt(e.end));if(!e.time)lines.push('DTEND;VALUE=DATE:'+shift(e.date,1).replace(/-/g,''));if(e.notes)lines.push('DESCRIPTION:'+clean(e.notes));lines.push('END:VEVENT')}lines.push('END:VCALENDAR');downloadFile('HOME-calendar.ics',lines.join('\r\n')+'\r\n','text/calendar')}
function updateFocus(){let left=focusRemaining();let ring=$('#focusRing');if(ring)ring.style.setProperty('--progress',Math.max(0,Math.min(100,left/(plan.focus.minutes*60)*100))+'%');if(plan.focus.end&&left===0){plan.logs.push({id:uid(),label:plan.focus.label,minutes:plan.focus.minutes,at:Date.now()});plan.focus.end=0;plan.focus.remaining=plan.focus.minutes*60;savePlan();render();toast('Focus session complete');return}let el=$('#focusClock');if(el)el.textContent=countdown()}
setInterval(updateFocus,1000);document.addEventListener('visibilitychange',updateFocus);
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;let d=b.dataset;if(d.new){if(d.new==='event'&&tab==='Overview')selectedDay=shift(dayKey(),['Evening','Night'].includes(periodNow())?1:0);openEditor(d.new);}else if(d.edit){let [k,id]=d.edit.split(':');openEditor(k,id)}else if('close'in d)$('#editor').close();else if(d.delete){let [k,id]=d.delete.split(':');if(confirm('Delete this item?')){plan[collections[k]]=plan[collections[k]].filter(x=>x.id!==id);savePlan();$('#editor').close();render()}}else if(d.day){selectedDay=d.day;render()}else if(d.calmode){calMode=d.calmode;render()}else if(d.calnav){if(d.calnav==='today')selectedDay=dayKey();else if(calMode==='Month'){let x=asDate(selectedDay);x.setDate(1);x.setMonth(x.getMonth()+Number(d.calnav));selectedDay=dayKey(x)}else selectedDay=shift(selectedDay,Number(d.calnav)*(calMode==='Week'?7:1));render()}else if(d.taskfilter){taskFilter=d.taskfilter;render()}else if(d.roomgo){room=d.roomgo;navigate('Lighting')}else if(d.duration){plan.focus.minutes=Number(d.duration);plan.focus.remaining=plan.focus.minutes*60;plan.focus.end=0;savePlan();render()}else if(d.focus){if(d.focus==='start')plan.focus.end=Date.now()+(plan.focus.remaining||plan.focus.minutes*60)*1000;if(d.focus==='pause'){plan.focus.remaining=focusRemaining();plan.focus.end=0}if(d.focus==='reset'){plan.focus.end=0;plan.focus.remaining=plan.focus.minutes*60}savePlan();render()}else if(d.data==='export')exportBackup();else if(d.data==='import')$('#importFile').click();else if(d.data==='ics')exportICS()});
document.addEventListener('submit',e=>{if(e.target.id==='itemForm'){e.preventDefault();commitEditor(e.target)}});document.addEventListener('change',async e=>{let d=e.target.dataset;if(d.task||d.goal){let t=plan[d.task?'tasks':'goals'].find(x=>x.id===(d.task||d.goal));if(t){t.done=e.target.checked;if(d.goal&&t.target)t.progress=t.done?t.target:0;}savePlan();render()}if(e.target.id==='focusLabel'){plan.focus.label=e.target.value;savePlan()}if(e.target.id==='importFile'){try{let f=e.target.files[0];if(f){if(f.size>5000000)throw Error('Backup too large');importBackup(await f.text())}}catch(err){toast('Could not import: '+err.message)}e.target.value=''}});

document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;let d=b.dataset;if(d.tab)navigate(d.tab);else if(d.scene)choose(d.scene);else if(d.room){room=d.room;render()}else if(d.toggle){let l=state.lights.find(x=>x.id===d.toggle);l.on=!l.on;state.scene='Custom';save();render()}else if(d.action){switch(d.action){case'all':{let on=!state.lights.some(l=>l.on);state.lights.forEach(l=>l.on=on);state.scene='Custom';break}case'tv':state.tv=!state.tv;break;case'reset':if(confirm('Reset all local HOME data, including productivity items?')){state=JSON.parse(JSON.stringify(defaults));plan=freshPlan();savePlan()};break}save();render()}});
document.addEventListener('input',e=>{let d=e.target.dataset;if(d.bright){let l=state.lights.find(x=>x.id===d.bright),v=Number(e.target.value);l.b=v||l.b;l.on=v>0;state.scene='Custom';$('#b-'+l.id).textContent=v+'%';save()}if(d.temp){let l=state.lights.find(x=>x.id===d.temp);l.k=Number(e.target.value);state.scene='Custom';$('#k-'+l.id).textContent=l.k+'K';save()}if('volume'in d){state.volume=Number(e.target.value);$('#vol').textContent=state.volume+'%';save()}});document.addEventListener('change',e=>{if(e.target.matches('[data-bright],[data-temp]'))render()});/*START_V04*/if('serviceWorker'in navigator&&window.isSecureContext)navigator.serviceWorker.register('sw.js').catch(()=>{});
// HOME v0.4: adaptive display + live weather. All settings remain local.
const readLocal=(k,f)=>{try{return JSON.parse(localStorage.getItem(k)||'null')??f}catch{return f}};
const writeLocal=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v))}catch{}};
const displayDefaults={mode:'Auto',morning:'06:00',day:'10:00',evening:'17:00',night:'22:00',idle:5,city:null};
let display={...displayDefaults,...readLocal('home-display-v4',{})},nightDismissed='',lastPeriod='',lastDay=dayKey(),lastActivity=Date.now(),ambient=false,weather=readLocal('home-weather-v4',null),weatherError='',weatherBusy=false,cityResults=[];
function periodNow(){if(display.mode!=='Auto')return display.mode;let n=new Date(),t=n.getHours()*60+n.getMinutes(),pairs=[['Morning',display.morning],['Daytime',display.day],['Evening',display.evening],['Night',display.night]];let result='Night';for(let [name,v] of pairs){let [h,m]=v.split(':').map(Number);if(t>=h*60+m)result=name}return result}
function setDisplay(){writeLocal('home-display-v4',display);nightDismissed='';lastPeriod='';renderAdaptive(true)}
function displayConfig(){return `<section class="glass section"><h2>Display & atmosphere</h2><p class="note">Automatic layout follows your device clock. It never changes physical lights or interrupts an editor.</p><form id="displayForm" class="formgrid"><label>Dashboard<select name="mode">${['Auto','Morning','Daytime','Evening','Night'].map(x=>`<option ${display.mode===x?'selected':''}>${x}</option>`).join('')}</select></label><div class="grid two">${[['morning','Morning starts'],['day','Daytime starts'],['evening','Evening starts'],['night','Night starts']].map(([k,n])=>`<label>${n}<input type="time" name="${k}" required value="${esc(display[k])}"></label>`).join('')}</div><label>Ambient display after inactivity<select name="idle">${[0,1,3,5,10,15,30].map(n=>`<option value="${n}" ${display.idle===n?'selected':''}>${n?n+' minutes':'Never'}</option>`).join('')}</select></label><button class="primary" type="submit">Save display settings</button></form></section>`}
function weatherConfig(){return `<section class="glass section"><h2>Weather location</h2><p class="note">${display.city?'Selected: '+esc(display.city.label):'Choose a city to enable live weather.'} Location is not requested automatically. City queries and coordinates are sent to Open-Meteo.</p><form id="cityForm" class="row"><input name="city" placeholder="Search city (e.g. Tucson)" required minlength="2" maxlength="80" aria-label="City name"><button class="secondary">Search</button></form><div id="cityResults" class="cityresults"></div><p class="note">Forecast data: <a href="https://open-meteo.com/" target="_blank" rel="noopener" class="musiclink">Open-Meteo</a> · free for personal, non-commercial use.</p></section>`}
function settingsV3(){return displayConfig()+weatherConfig()+syncSettings()+`<section class="glass section"><h2>Data & connectivity</h2><p class="note">Install from HTTPS for offline app loading. Back up regularly; browser storage can be cleared. Apple Calendar and Reminders are not connected.</p><div class="syncbuttons"><button class="secondary" data-data="export">Export backup</button><button class="secondary" data-data="import">Import backup</button><button class="secondary" data-data="ics">Export calendar (.ics)</button></div></section><section class="section">${settings()}</section>`}
const wxInfo=c=>c===0?['Clear','sun']:c===1?['Mostly clear','sun']:c===2?['Partly cloudy','cloud']:c===3?['Overcast','cloud']:c===45||c===48?['Fog','cloud']:c>=95?['Thunderstorms','storm']:c>=71&&c<=77||c===85||c===86?['Snow','snow']:c>=51&&c<=67||c>=80&&c<=82?['Rain','rain']:['Conditions unavailable','cloud'];
Object.assign(paths,{cloud:'<path d="M6 18a4 4 0 0 1-1-8 6 6 0 0 1 11-2 5 5 0 1 1 2 10Z"/>',rain:'<path d="M6 14a4 4 0 0 1-1-8 6 6 0 0 1 11-2 5 5 0 1 1 2 10ZM8 17l-1 3m5-3-1 3m5-3-1 3"/>',snow:'<path d="M12 2v20M3.3 7l17.4 10M3.3 17l17.4-10M9 4l3 3 3-3M9 20l3-3 3 3"/>',storm:'<path d="M6 14a4 4 0 0 1-1-8 6 6 0 0 1 11-2 5 5 0 1 1 2 10h-4l-3 5h4l-4 4"/>'});
function weatherCard(full=true){if(!display.city)return `<div class="weather-empty">${icon('cloud')}<div><h3>Weather</h3><p class="muted">Choose your city for live conditions.</p></div><button class="textbutton" data-tab="Settings">Set location ›</button></div>`;if(!weather||weather.city!==display.city.label)return `<div class="weather-empty">${icon('cloud')}<div><h3>${esc(display.city.label)}</h3><p class="muted">${weatherBusy?'Updating forecast…':esc(weatherError||'Weather not loaded yet.')}</p></div><button class="textbutton" data-weather-refresh>Refresh</button></div>`;
let w=weather.data,c=w.current,d=w.daily,h=w.hourly,info=wxInfo(c.weather_code),i=h.time.findIndex(t=>t>=c.time.slice(0,13)+':00');if(i<0)i=0;let stale=Date.now()-weather.at>30*60000||!!weatherError||!navigator.onLine;let degree=v=>v==null?'—':Math.round(v)+'°';return `<div class="weather-summary"><div><p class="weather-location">${esc(display.city.label)}</p><div class="weather-temp">${degree(c.temperature_2m)}</div><p>${info[0]} · H ${degree(d.temperature_2m_max[0])} / L ${degree(d.temperature_2m_min[0])}</p></div><span class="weather-symbol">${icon(c.weather_code===0&&c.is_day===0?'moon':info[1])}</span></div>${full?`<div class="hourly">${h.time.slice(i,i+6).map((t,j)=>`<div><small>${j===0?'Now':fmtTime(t.slice(11,16))}</small>${icon(wxInfo(h.weather_code[i+j])[1])}<strong>${degree(h.temperature_2m[i+j])}</strong><small>${h.precipitation_probability[i+j]??'—'}%</small></div>`).join('')}</div><div class="weather-metrics"><div>Feels like<strong>${degree(c.apparent_temperature)}</strong></div><div>Humidity<strong>${c.relative_humidity_2m??'—'}%</strong></div><div>Wind<strong>${Math.round(c.wind_speed_10m)} mph</strong></div><div>UV max<strong>${d.uv_index_max[0]??'—'}</strong></div><div>Sunrise<strong>${fmtTime(d.sunrise[0].slice(11,16))}</strong></div><div>Sunset<strong>${fmtTime(d.sunset[0].slice(11,16))}</strong></div></div><details class="forecast-details"><summary>7-day forecast</summary>${d.time.map((t,j)=>`<div class="forecast-row"><span>${j===0?'Today':pretty(t)}</span>${icon(wxInfo(d.weather_code[j])[1])}<span>${d.precipitation_probability_max[j]??'—'}%</span><strong>${degree(d.temperature_2m_min[j])} / ${degree(d.temperature_2m_max[j])}</strong></div>`).join('')}</details>`:''}<div class="weather-meta"><span>${stale?'Last available · ':'Updated '}${new Date(weather.at).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'})} · Open-Meteo</span><button class="textbutton" data-weather-refresh>Refresh</button></div>`}
function refreshWeatherUI(){let code=weather?.data?.current?.weather_code;document.body.dataset.weather=weather?.city===display.city?.label&&code!=null?(code>=51?'rain':code>=2?'cloud':'clear'):'unknown';document.querySelectorAll('[data-weather-box]').forEach(el=>el.innerHTML=weatherCard(el.dataset.weatherBox==='full'));let hero=$('#heroWeather');if(hero)hero.innerHTML=heroWeather();if(ambient)updateAmbient();}
async function requestJSON(url,opts={}){let r=await fetch(url,{...opts,cache:'no-store'});if(!r.ok)throw Error('Request failed ('+r.status+')');return r.json()}
async function fetchWeather(force=false){if(!display.city||weatherBusy)return;if(!force&&weather?.city===display.city.label&&Date.now()-weather.at<15*60000)return;let city=display.city;weatherBusy=true;refreshWeatherUI();try{let p=new URLSearchParams({latitude:city.lat,longitude:city.lon,temperature_unit:'fahrenheit',wind_speed_unit:'mph',timezone:'auto',forecast_days:7,current:'temperature_2m,relative_humidity_2m,apparent_temperature,is_day,weather_code,wind_speed_10m',hourly:'temperature_2m,weather_code,precipitation_probability',daily:'temperature_2m_max,temperature_2m_min,weather_code,precipitation_probability_max,sunrise,sunset,uv_index_max'});let data=await requestJSON('https://api.open-meteo.com/v1/forecast?'+p);if(display.city?.label===city.label){weather={city:city.label,data,at:Date.now()};writeLocal('home-weather-v4',weather);weatherError=''}}catch{weatherError='Weather unavailable. Check internet connection.'}finally{weatherBusy=false;refreshWeatherUI();if(display.city?.label!==city.label)fetchWeather(true)}}
function weatherPanel(full=true){return `<section class="glass weather-panel" data-weather-box="${full?'full':'compact'}">${weatherCard(full)}</section>`}
const goalColors=['#a875ff','#46a2ff','#49df93','#ffad65'];
const eventColors={Blue:'#49a8ff',Purple:'#ab71ff',Green:'#42db89',Orange:'#ffac55',Pink:'#ff739d'};
function appleCalendar(){let d=new Date();return `<span class="calendar-icon"><small>${d.toLocaleDateString('en-US',{weekday:'short'}).toUpperCase()}</small><b>${d.getDate()}</b></span>`}
function cardTitle(i,t,button=''){return `<div class="cardhead">${i==='calendar'?appleCalendar():i==='music'?'<span class="music-icon">'+icon('music')+'</span>':icon(i)}<h2>${t}</h2>${button}</div>`}
function arrow(tab){return `<button class="circle-action" data-tab="${tab}" aria-label="Open ${tab}">${icon('right')}</button>`}
function plus(kind){return `<button class="circle-action" data-new="${kind}" aria-label="Add ${kind}">${icon('plus')}</button>`}
function heroWeather(){let c=weather?.data?.current;if(!display.city)return `<button class="hero-location" data-tab="Settings">${icon('cloud')} Set weather location ›</button>`;if(!c||weather.city!==display.city.label)return `<button class="hero-location" data-tab="Weather">${icon('cloud')} ${esc(weatherBusy?'Updating weather…':weatherError||'Weather unavailable')} ›</button>`;let stale=Date.now()-weather.at>1800000||!!weatherError||!navigator.onLine;let info=wxInfo(c.weather_code);let symbol=c.weather_code<=1?(c.is_day===0?'🌙':'☀️'):c.weather_code===2?'🌤️':info[1]==='rain'?'🌧️':info[1]==='snow'?'🌨️':'☁️';return `<button class="hero-weather" data-tab="Weather"><span class="wxemoji" aria-hidden="true">${symbol}</span><span><strong>${Math.round(c.temperature_2m)}°</strong><small>${esc(info[0])}${stale?' · Cached':''}</small><small>${esc(display.city.label.split(',')[0])} · ${new Date(weather.at).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'})}</small></span></button>`}
function goalRows(editable=false){return plan.goals.length?plan.goals.slice(0,editable?10000:3).map((g,i)=>{let target=Number(g.target)||1,progress=Number(g.progress??(g.done?target:0))||0;return `<div class="goalrow"><div class="between"><span>${esc(g.title)}</span>${editable?`<button class="tiny" data-edit="goal:${esc(g.id)}" aria-label="Edit goal">${icon('edit')}</button>`:''}</div><div class="goalmetric"><div class="goaltrack"><span style="width:${Math.min(100,Math.max(0,progress/target*100))}%;background:${goalColors[i%4]}"></span></div><small>${progress.toLocaleString()} / ${target.toLocaleString()} ${esc(g.unit||'')}</small></div></div>`}).join(''):'<p class="empty">Set a goal and track your progress.</p>'}
function goalsView(){return `<section class="glass">${cardTitle('target','Your goals',plus('goal'))}${goalRows(true)}</section>`}
function dashboardAgenda(day){let all=eventsOn(day),now=new Date(),cut=String(now.getHours()).padStart(2,'0')+':'+String(now.getMinutes()).padStart(2,'0');let es=(day===dayKey()?all.filter(e=>!e.time||(e.end||e.time)>=cut):all).slice(0,4);return es.length?es.map((e,i)=>`<button class="agenda-item" data-edit="event:${esc(e.id)}"><time>${esc(fmtTime(e.time))}</time><span style="--event:${eventColors[e.color]||Object.values(eventColors)[i%5]}">${esc(e.title)}</span></button>`).join(''):'<p class="empty">No upcoming events.</p>'}
function todayView(){let mode=periodNow(),tomorrow=['Evening','Night'].includes(mode),day=tomorrow?shift(dayKey(),1):dayKey(),d=new Date(),greet={Morning:'Good morning',Daytime:'Good afternoon',Evening:'Good evening',Night:'Good night'}[mode];return `<div class="homegrid"><section class="glass hero-v5"><div class="hero-date">${esc(d.toLocaleDateString([],{weekday:'long',month:'short',day:'numeric'}))}</div><div class="hero-clock" id="heroClock">${esc(d.toLocaleTimeString([],{hour:'numeric',minute:'2-digit'}).replace(/\s*(AM|PM)$/i,''))}</div><div id="heroWeather">${heroWeather()}</div><button class="ambient-trigger" data-ambient aria-label="Ambient display">${icon('moon')}</button></section><section class="glass dash-agenda">${cardTitle('calendar',tomorrow?'Tomorrow':'Up Next',arrow('Calendar'))}${dashboardAgenda(day)}<button class="textbutton" data-new="event">+ New event</button></section><section class="glass dash-tasks">${cardTitle('tasks','Tasks',plus('task'))}${taskRows(plan.tasks.filter(t=>!t.done).slice(0,4))}<button class="textbutton" data-tab="Tasks">All tasks ›</button></section><section class="glass dash-focus">${cardTitle('target','Focus')}${focusCard()}</section><section class="glass dash-goals">${cardTitle('target','Goals',arrow('Goals'))}${goalRows()}<button class="textbutton" data-new="goal">+ New goal</button></section><section class="glass dash-home">${cardTitle('home','Smart Home',arrow('Lighting'))}<p class="muted">Simulated accessories</p>${roomCards()}<div class="section">${sceneCards()}</div></section></div>`}

function updateAmbient(){let el=$('#ambientDisplay');if(!el||el.hidden)return;let d=new Date(),night=periodNow()==='Night',t=d.toLocaleTimeString([],{hour:'numeric',minute:'2-digit'}),events=eventsOn(shift(dayKey(),night||periodNow()==='Evening'?1:0)),next=events.find(e=>!e.time||night||periodNow()==='Evening'||e.time>=String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0'));let c=weather?.data?.current;el.className='ambient-display '+(night?'night':'');let content=`<div class="ambient-date">${esc(d.toLocaleDateString([],{weekday:'long',month:'long',day:'numeric'}))}</div><div class="ambient-clock">${esc(t.replace(/\s*(AM|PM)$/i,''))}<small>${esc(t.match(/AM|PM/i)?.[0]||'')}</small></div><div class="ambient-weather">${c&&weather.city===display.city?.label?`${icon(wxInfo(c.weather_code)[1])} ${Math.round(c.temperature_2m)}° · ${wxInfo(c.weather_code)[0]}${Date.now()-weather.at>1800000?' · Last available':''}`:'Weather not available'}</div><div class="ambient-next"><small>${night||periodNow()==='Evening'?'TOMORROW':'UP NEXT'}</small><div>${next?esc(fmtTime(next.time)+' · '+next.title):'Nothing scheduled'}</div></div><button data-close-ambient class="ambient-exit">Tap to return to HOME</button>`;if(el.dataset.content!==content){el.innerHTML=content;el.dataset.content=content}}
function showAmbient(){if($('#editor').open)return;ambient=true;let el=$('#ambientDisplay');el.hidden=false;updateAmbient()}
function hideAmbient(){ambient=false;$('#ambientDisplay').hidden=true;nightDismissed=periodNow();lastActivity=Date.now()}
function renderAdaptive(force=false){let p=periodNow(),day=dayKey();document.body.dataset.period=p.toLowerCase();let changed=lastPeriod!==p||lastDay!==day;let safe=!$('#editor').open&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName);if(safe&&(changed||force)){lastPeriod=p;lastDay=day;if(tab==='Overview')render();if(p==='Night'&&tab==='Overview'&&nightDismissed!==p&&!matchMedia('(max-width: 640px)').matches)showAmbient();if(p!=='Night'&&ambient)hideAmbient()}if(safe&&!ambient&&tab==='Overview'&&!matchMedia('(max-width: 640px)').matches&&!plan.focus.end&&display.idle>0&&Date.now()-lastActivity>=display.idle*60000)showAmbient();if(ambient)updateAmbient()}
let ambientEl=document.createElement('div');ambientEl.id='ambientDisplay';ambientEl.hidden=true;ambientEl.setAttribute('role','region');ambientEl.setAttribute('aria-label','Ambient display');document.body.append(ambientEl);
['pointerdown','keydown','touchstart'].forEach(x=>document.addEventListener(x,()=>{lastActivity=Date.now()},{passive:true}));
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if('ambient'in b.dataset)showAmbient();if('closeAmbient'in b.dataset)hideAmbient();if('weatherRefresh'in b.dataset)fetchWeather(true);if('cityIndex'in b.dataset){let c=cityResults[Number(b.dataset.cityIndex)];if(!c)return;display.city={label:[c.name,c.admin1,c.country].filter(Boolean).join(', '),lat:c.latitude,lon:c.longitude};weather=null;weatherError='';setDisplay();render();fetchWeather(true);toast('Weather location saved')}});
document.addEventListener('submit',async e=>{let f=e.target;if(f.id==='displayForm'){e.preventDefault();let data=Object.fromEntries(new FormData(f)),times=['morning','day','evening','night'].map(k=>data[k]);if(!times.every((v,i)=>i===0||v>times[i-1]))return toast('Choose times in increasing order.');display={...display,...data,idle:Number(data.idle)};setDisplay();toast('Display preferences saved')}if(f.id==='cityForm'){e.preventDefault();let res=$('#cityResults');res.textContent='Searching…';try{let data=await requestJSON('https://geocoding-api.open-meteo.com/v1/search?'+new URLSearchParams({name:new FormData(f).get('city'),count:8,language:'en',format:'json'}));cityResults=data.results||[];res.innerHTML=cityResults.length?cityResults.map((c,i)=>`<button class="secondary city-choice" data-city-index="${i}">${esc([c.name,c.admin1,c.country].filter(Boolean).join(', '))}</button>`).join(''):'No matching cities. Try a nearby city.'}catch{res.textContent='City search unavailable. Try again online.'}}});
setInterval(()=>renderAdaptive(),1000);setInterval(()=>fetchWeather(),60000);document.addEventListener('visibilitychange',()=>{if(!document.hidden){lastActivity=Date.now();renderAdaptive();fetchWeather()}});window.addEventListener('online',()=>fetchWeather(true));
// Optional Supabase sync. Public publishable/anon key only; RLS is mandatory.
const syncKinds=['events','tasks','goals','logs'];
let syncCfg=readLocal('home-sync-config-v4',null),syncSession=readLocal('home-sync-session-v4',null),syncOwner=readLocal('home-sync-owner-v4',''),outbox=readLocal('home-sync-outbox-v4',{}),syncBusy=false,syncStatus='Not connected',syncRetry=0,syncTimer=0,baseline=recordMap();
function recordMap(){let m={};for(let k of syncKinds)for(let item of plan[k])m[k+':'+item.id]={kind:k,item_id:item.id,payload:item,deleted:false};return JSON.parse(JSON.stringify(m))}
function syncCapture(){let next=recordMap();if(syncOwner){for(let k of new Set([...Object.keys(baseline),...Object.keys(next)])){if(JSON.stringify(baseline[k])!==JSON.stringify(next[k])){outbox[k]={...(next[k]||{...baseline[k],payload:null,deleted:true}),change:uid()}}}writeLocal('home-sync-outbox-v4',outbox);clearTimeout(syncTimer);syncTimer=setTimeout(runSync,750)}baseline=next}
function syncSecure(){return location.protocol==='https:'||location.hostname==='localhost'||location.hostname==='127.0.0.1'}
function syncSettings(){return `<section class="glass section"><h2>Device synchronization</h2><p class="note" id="syncStatus">${esc(syncStatus)}${syncOwner?' · Account linked on this device':''}</p><p class="note">Optional free Supabase project. Calendar, tasks, goals and completed activity records sync; running timers, display preferences and simulated room controls stay device-specific. Same-item conflicts use last successful write.</p>${!syncSecure()?'<p class="note">For security, sign-in is available only on HTTPS or localhost. Do not enter credentials on the unencrypted iPad LAN address.</p>':syncSession?`<div class="syncbuttons"><button class="secondary" data-sync="now">Sync now</button><button class="secondary" data-sync="out">Sign out</button></div>`:`<form id="syncForm" class="formgrid"><label>Supabase project URL<input type="url" name="url" placeholder="https://your-project.supabase.co" required value="${esc(syncCfg?.url||'')}"></label><label>Publishable or legacy anon key<input name="key" required value="${esc(syncCfg?.key||'')}" autocomplete="off"></label><label>Email<input type="email" name="email" required autocomplete="username"></label><label>Password<input type="password" name="password" required autocomplete="current-password"></label><button class="primary">Sign in & connect</button></form>`}<p class="note">Setup: run the included SQL in your own Supabase project and create your private user. No service-role or secret keys. No paid plan needed. Keep backups.</p></section>`}
function statusSync(s){syncStatus=s;let el=$('#syncStatus');if(el)el.textContent=s+(syncOwner?' · Account linked on this device':'')}
function checkConfig(url,key){let u=new URL(url);if(u.protocol!=='https:'||!/^([a-z0-9-]+)\.supabase\.co$/.test(u.hostname)||u.port||u.username||u.password||u.pathname!=='/'||u.search||u.hash)throw Error('Use your HTTPS Supabase project URL.');if(key.startsWith('sb_secret_'))throw Error('Use a publishable or anon key, never a secret key.');if(!key.startsWith('sb_publishable_')){let payload;try{payload=JSON.parse(atob(key.split('.')[1].replace(/-/g,'+').replace(/_/g,'/')))}catch{}if(payload?.role!=='anon')throw Error('Use a publishable or legacy anon key.')}return {url:u.origin,key}}
async function authRequest(cfg,grant,body){let r=await fetch(cfg.url+'/auth/v1/token?grant_type='+grant,{method:'POST',headers:{apikey:cfg.key,'Content-Type':'application/json'},body:JSON.stringify(body)});if(!r.ok)throw Error('Sign-in or session refresh failed ('+r.status+').');let j=await r.json();if(!j.access_token||!j.user?.id)throw Error('Invalid session');return {...j,expires_at:Math.floor(Date.now()/1000)+(j.expires_in||3600)}}
async function accessToken(){if(!syncSession)throw Error('Sign in first');if(syncSession.expires_at<Date.now()/1000+90){let session=await authRequest(syncCfg,'refresh_token',{refresh_token:syncSession.refresh_token});if(session.user.id!==syncOwner)throw Error('Account mismatch');syncSession=session;writeLocal('home-sync-session-v4',session)}return syncSession.access_token}
async function dbRequest(path,method='GET',body){let token=await accessToken();let r=await fetch(syncCfg.url+'/rest/v1/home_records'+path,{method,headers:{apikey:syncCfg.key,Authorization:'Bearer '+token,'Content-Type':'application/json',...(method==='POST'?{Prefer:'resolution=merge-duplicates,return=minimal'}:{})},...(body?{body:JSON.stringify(body)}:{})});if(!r.ok)throw Error('Database request failed ('+r.status+'). Verify SQL and permissions.');return method==='GET'?r.json():null}
async function runSync(){if(!syncSession||!syncSecure()||syncBusy||!navigator.onLine||$('#editor').open)return;if(Date.now()<syncRetry)return;syncBusy=true;statusSync('Syncing…');try{let rows=Object.entries(outbox);for(let i=0;i<rows.length;i+=100){let chunk=rows.slice(i,i+100);await dbRequest('?on_conflict=user_id,kind,item_id','POST',chunk.map(([k,{change,...r}])=>({...r,user_id:syncOwner})));for(let [k,r] of chunk)if(outbox[k]?.change===r.change)delete outbox[k];writeLocal('home-sync-outbox-v4',outbox)}let remote={};for(let offset=0;;offset+=500){let batch=await dbRequest('?select=kind,item_id,payload,deleted&order=kind.asc,item_id.asc&limit=500&offset='+offset);for(let r of batch)if(syncKinds.includes(r.kind))remote[r.kind+':'+r.item_id]=r;if(batch.length<500)break;if(offset>=19500)throw Error('Too many records; export a backup.')}let merged={...remote,...outbox};let before=JSON.stringify(syncKinds.map(k=>plan[k]));for(let k of syncKinds)plan[k]=Object.values(merged).filter(r=>r.kind===k&&!r.deleted&&r.payload?.id===r.item_id).map(r=>r.payload);baseline=recordMap();writeLocal('home-plan-v3',plan);statusSync('Synced '+new Date().toLocaleTimeString([],{hour:'numeric',minute:'2-digit'}));if(before!==JSON.stringify(syncKinds.map(k=>plan[k]))&&!$('#editor').open&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName)&&tab!=='Settings')render();}catch(e){syncRetry=Date.now()+30000;statusSync('Sync unavailable · changes kept locally. '+e.message)}finally{syncBusy=false}}
document.addEventListener('submit',async e=>{if(e.target.id!=='syncForm')return;e.preventDefault();if(!syncSecure()||syncBusy)return;let f=e.target,data=Object.fromEntries(new FormData(f)),btn=f.querySelector('button');btn.disabled=true;try{let cfg=checkConfig(data.url,data.key),session=await authRequest(cfg,'password',{email:data.email,password:data.password});if(syncOwner&&(syncOwner!==session.user.id||syncCfg?.url!==cfg.url))throw Error('This browser is linked to a different account/project. Use a separate browser profile.');if(!syncOwner&&Object.keys(recordMap()).length&&!confirm('Merge and upload this device’s existing calendar, tasks, goals and activity to this account?'))return;syncCfg=cfg;syncSession=session;if(!syncOwner){syncOwner=session.user.id;for(let [k,r] of Object.entries(recordMap()))outbox[k]={...r,change:uid()};writeLocal('home-sync-owner-v4',syncOwner);writeLocal('home-sync-outbox-v4',outbox)}writeLocal('home-sync-config-v4',cfg);writeLocal('home-sync-session-v4',session);syncRetry=0;statusSync('Connected');render();await runSync()}catch(err){statusSync(err.message);toast(err.message)}finally{btn.disabled=false;f.elements.password.value=''}});
document.addEventListener('click',e=>{let action=e.target.closest('[data-sync]')?.dataset.sync;if(action==='now'){syncRetry=0;runSync()}if(action==='out'&&!syncBusy){syncSession=null;localStorage.removeItem('home-sync-session-v4');statusSync('Signed out · local data retained');render()}});
setInterval(()=>{if(!document.hidden)runSync()},15000);window.addEventListener('online',()=>{syncRetry=0;runSync()});document.addEventListener('visibilitychange',()=>{if(!document.hidden)runSync()});

