function searchHome(q){let results=$('#searchResults');if(!results)return;q=q.trim().toLowerCase();let records=[...plan.events.map(x=>[x,'event']),...plan.tasks.map(x=>[x,'task']),...plan.goals.map(x=>[x,'goal'])];let matches=q?records.filter(([x])=>x.title.toLowerCase().includes(q)).slice(0,30):[];results.innerHTML=matches.length?matches.map(([x,k])=>`<button class="search-result" data-search-edit="${k}:${esc(x.id)}">${esc(x.title)}<small>${k}</small></button>`).join(''):`<p class="empty">${q?'No matches':'Search your personal information.'}</p>`}
document.addEventListener('input',e=>{if(e.target.id==='homeSearch')searchHome(e.target.value)});document.addEventListener('click',e=>{let b=e.target.closest('[data-search-edit]');if(b){let [k,id]=b.dataset.searchEdit.split(':');$('#editor').close();openEditor(k,id)}});


